-- Report:  RPT_052_REIM_Unmatched_Receipts
-- Module:  Cost
-- Source:  RPT_052_REIM_Unmatched_Receipts.dva
-- Generated by MFCS DVA SQL Extractor


-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT     sh.SHIPMENT                                          AS \"Receipt Number\",     sh.RECEIVE_DATE                                      AS \"Receipt Date\",     sh.ASN                                                AS \"ASN Number\",      oh.ORDER_NO                                          AS \"PO Number\",     oh.STATUS                                            AS \"PO Status\",     oh.OTB_EOW_DATE                                      AS \"PO Date\",      oh.SUPPLIER                                          AS \"Supplier ID\",     sp.SUP_NAME                                          AS \"Supplier Name\",     sp.SUP_STATUS                                        AS \"Supplier Status\",      ol.LOCATION                                          AS \"Location ID\",     ol.LOC_TYPE                                          AS \"Location Type\",     CASE ol.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                  AS \"Location Name\",      ss.ITEM                                              AS \"Item ID\",     im.ITEM_DESC                                         AS \"Item Description\",     im.DEPT                                              AS \"Department Number\",     d.DEPT_NAME                                          AS \"Department Name\",      ss.QTY_RECEIVED                                      AS \"Quantity Received\",     ss.UNIT_COST                                         AS \"Unit Cost\",     ROUND(ss.QTY_RECEIVED * ss.UNIT_COST, 2)            AS \"Receipt Cost Value\",      TRUNC(SYSDATE) - TRUNC(sh.RECEIVE_DATE)             AS days_since_receipt,     CASE         WHEN TRUNC(SYSDATE) - TRUNC(sh.RECEIVE_DATE) BETWEEN 0  AND 7              THEN '0 - 7 Days'         WHEN TRUNC(SYSDATE) - TRUNC(sh.RECEIVE_DATE) BETWEEN 8  AND 15              THEN '8 - 15 Days'         WHEN TRUNC(SYSDATE) - TRUNC(sh.RECEIVE_DATE) BETWEEN 16 AND 30              THEN '16 - 30 Days'         WHEN TRUNC(SYSDATE) - TRUNC(sh.RECEIVE_DATE) &gt; 30              THEN '30+ Days'     END                                                  AS \"Aging Bucket\",      ss.INVC_MATCH_STATUS                                 AS \"Ship SKU Match Status\",     sh.INVC_MATCH_STATUS                                 AS \"Shipment Match Status\",     sh.INVC_MATCH_DATE                                   AS \"Invoice Match Date\",      dh.DOC_ID                                            AS \"ReIM Invoice Document ID\",     dh.STATUS                                            AS \"ReIM Document Status\",     dh.HOLD_STATUS                                       AS \"ReIM Hold Status\",      CASE         WHEN ss.INVC_MATCH_STATUS IS NULL              OR ss.INVC_MATCH_STATUS IN ('U', 'UNM', 'UNMATCHED')             THEN 'NO INVOICE MATCHED TO RECEIPT'         WHEN ss.INVC_MATCH_STATUS = 'P'             THEN 'PARTIALLY MATCHED'         ELSE ss.INVC_MATCH_STATUS     END                                                  AS \"Unmatched Reason\",      TRUNC(SYSDATE)                                       AS \"Report Date\"  FROM     MFCS_RDS.RDS_WV_SHIPMENT             sh     JOIN  MFCS_RDS.RDS_WV_SHIPSKU         ss   ON  sh.SHIPMENT       = ss.SHIPMENT     JOIN  MFCS_RDS.RDS_WV_ORDHEAD         oh   ON  sh.ORDER_NO       = oh.ORDER_NO     JOIN  MFCS_RDS.RDS_WV_ORDLOC          ol   ON  oh.ORDER_NO       = ol.ORDER_NO                                               AND  ss.ITEM            = ol.ITEM                                               AND  sh.TO_LOC          = ol.LOCATION     JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER     im   ON  ss.ITEM            = im.ITEM     JOIN  MFCS_RDS.RDS_WV_DEPS            d    ON  im.DEPT            = d.DEPT     LEFT JOIN MFCS_RDS.RDS_WV_SUPS         sp  ON  oh.SUPPLIER        = sp.SUPPLIER     LEFT JOIN MFCS_RDS.RDS_WV_STORE        st  ON  ol.LOCATION        = st.STORE                                               AND  ol.LOC_TYPE         = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH          wh   ON  ol.LOCATION        = wh.WH                                               AND  ol.LOC_TYPE         = 'W'      LEFT JOIN MFCS_RDS.RDS_WV_IM_DOC_HEAD  dh  ON  oh.ORDER_NO        = dh.ORDER_NO                                               AND  oh.SUPPLIER         = TO_NUMBER(dh.VENDOR)                                               AND  dh.STATUS          != 'M'     WHERE     (ss.INVC_MATCH_STATUS IS NULL      OR ss.INVC_MATCH_STATUS IN ('U', 'UNM', 'UNMATCHED', 'P'))      AND sh.RECEIVE_DATE &gt;= ADD_MONTHS(SYSDATE, -3)     ORDER BY     days_since_receipt  DESC,     sp.SUP_NAME,     sh.SHIPMENT,     ss.ITEM</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>Receipt Number</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Receipt Date</ds:name><ds:datatype>timestamp</ds:datatype></ds:column><ds:column><ds:name>ASN Number</ds:name><ds:datatype>varchar(30)</ds:datatype></ds:column><ds:column><ds:name>PO Number</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>PO Status</ds:name><ds:datatype>varchar(1)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>PO Date</ds:name><ds:datatype>timestamp</ds:datatype></ds:column><ds:column><ds:name>Supplier ID</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Supplier Name</ds:name><ds:datatype>varchar(240)</ds:datatype></ds:column><ds:column><ds:name>Supplier Status</ds:name><ds:datatype>varchar(1)</ds:datatype></ds:column><ds:column><ds:name>Location ID</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Location Type</ds:name><ds:datatype>varchar(1)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Location Name</ds:name><ds:datatype>varchar(150)</ds:datatype></ds:column>